<?php $channels=$channels??[]; ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Payment Methods | EduSasa</title><style>body{font-family:system-ui,sans-serif;background:#f6f7fb;color:#172033;margin:0}.wrap{max-width:1100px;margin:32px auto;padding:0 18px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:18px;margin-bottom:16px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:14px}input,select,textarea{width:100%;box-sizing:border-box;padding:9px;border:1px solid #ccd1db;border-radius:8px;margin:5px 0 12px}button,a{padding:9px 13px;border-radius:8px;border:0;background:#172033;color:#fff;text-decoration:none}.muted{color:#667085}.row{display:grid;grid-template-columns:1fr 1fr;gap:12px}.checks{display:flex;gap:14px;flex-wrap:wrap;margin:6px 0 14px}.checks label{display:flex;gap:5px;align-items:center}.checks input{width:auto;margin:0}.danger{background:#9b1c1c}@media(max-width:650px){.row{grid-template-columns:1fr}}</style></head><body><main class="wrap"><p><a href="/finance">← Finance</a></p><section class="card"><h1>Payment Methods</h1><p class="muted">Configure how this school accepts payments. Each school has its own channels; M-Pesa is not required.</p><form method="post" action="/finance/payment-methods/save"><div class="row"><label>Code<input name="code" placeholder="mpesa_paybill" required></label><label>Name<input name="name" placeholder="M-Pesa Paybill" required></label></div><div class="row"><label>Type<select name="type"><option value="mpesa">M-Pesa</option><option value="bank">Bank</option><option value="cash">Cash</option><option value="cheque">Cheque</option><option value="other">Other</option></select></label><label>Provider<input name="provider" placeholder="Safaricom / KCB / Equity..."></label></div><label>Configuration JSON<textarea name="config_json" rows="5">{"paybill":"","till":"","account_reference":"admission_number"}</textarea></label><label>Parent-facing instructions<textarea name="instructions" rows="3" placeholder="Payment instructions shown to parents"></textarea></label><div class="row"><label>Sort order<input type="number" min="0" name="sort_order" value="0"></label><label>Default<input type="checkbox" name="default" value="1"></label></div><div class="checks"><label><input type="checkbox" name="active" value="1" checked> Active</label><label><input type="checkbox" name="parent" value="1" checked> Parent payments</label><label><input type="checkbox" name="staff" value="1" checked> Staff entry</label><label><input type="checkbox" name="reference" value="1"> Requires reference</label></div><button>Save payment method</button></form></section><section class="grid"><?php foreach($channels as $channel): ?><article class="card"><h2><?= htmlspecialchars($channel['name']) ?></h2><p><strong><?= htmlspecialchars(strtoupper($channel['type'])) ?></strong> · <?= $channel['is_active']?'Active':'Disabled' ?><?= $channel['is_default']?' · Default':'' ?></p><p class="muted"><?= htmlspecialchars((string)($channel['provider']??'')) ?></p><pre><?= htmlspecialchars((string)($channel['config_json']??'{}')) ?></pre><p><?= nl2br(htmlspecialchars((string)($channel['instructions']??''))) ?></p><form method="post" action="/finance/payment-methods/delete"><input type="hidden" name="id" value="<?= (int)$channel['id'] ?>"><button class="danger" onclick="return confirm('Remove this payment method?')">Remove</button></form></article><?php endforeach;if(!$channels): ?><article class="card"><p class="muted">No payment methods configured yet.</p></article><?php endif; ?></section></main></body></html>